PREFIX res: <https://example.org/research/>
SELECT ?s ?type ?year ?src ?rs ?ret ?v WHERE {
  ?s a res:Work . FILTER(REGEX(STR(?s),"research/W(39|[4-9][0-9])$"))
  OPTIONAL{?s res:workType ?type} OPTIONAL{?s res:year ?year} OPTIONAL{?s res:source ?src}
  OPTIONAL{?s res:recordSource ?rs} OPTIONAL{?s res:retracted ?ret} OPTIONAL{?s res:versionOf ?v}
} ORDER BY ?s
```

